// Planted defects for client frameworks: React, Electron, Next.js and React Native / mobile, spread over six small projects
// (a website, a desktop app, a mobile app, an API, a static site and a monorepo). Each project has a "-clean" twin: the same files
// written the safe way, which must not be reported. One defect per file, five blank lines after it, so a neighbour cannot explain a hit.
// Keys and project names are prefixed `client-`. Secret values come from the corpus context (random parts joined at run time).
// In the text, § stands for a backtick and @{ for ${ (so this source needs no escaping).
// A key left out of `expect` has no matching check in packs/ yet (a known gap); it is still planted, and the report lists it.

const fix = (s) => (s ?? '').replaceAll('§', '`').replaceAll('@{', '${')

// cases: [key, file, expected check(s) or '' when no check exists, description, text before, bad text, good text, text after (optional)]
const mk = (name, ctx, cases, base = {}) => {
  const { d, tidy } = ctx
  const expect = {}
  const bad = { ...tidy(`client-${name}`), ...base }
  const good = { ...tidy(`client-${name}-clean`), ...base }
  for (const [k, file, exp, desc, pre, badText, goodText, post = ''] of cases) {
    if (exp) expect[`client-${k}`] = exp
    const tail = post ? [fix(post)] : []
    bad[file] = [fix(pre), d(`client-${k}`, desc, fix(badText)), ...tail, '', '', '', '', '']
    good[file] = [fix(pre), fix(goodText), ...tail, '']
  }
  return { projects: { [`client-${name}`]: { files: bad }, [`client-${name}-clean`]: { files: good } }, expect }
}

